import { create_list_edit_delete_category } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogDeleteCategory: Boolean,
    StoreObj: Object
  },
  components: {
    SnackBar
  },
  data: () => ({
    loading: false,
    SnackBarComponent: {}
  }),
  methods: {
    DialogDeleteCategoryEmit(Toggle) {
      this.$emit("clicked", Toggle);
    },
    async DeleteCategory() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_category, {
          input: {
            action_type: "DELETE",
            category_id: this.StoreObj.category_id
          }
        }));
        let resultObj = JSON.parse(result.data.create_list_edit_delete_category);
        if (resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: "☑️ " + resultObj.Message
          };
          this.$emit("refresh-list");
        } else {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "red",
            SnackbarText: "❎ " + resultObj.Message
          };
        }
        this.loading = false;
        this.DialogDeleteCategoryEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "❎ Failed to update category, try again!"
        };
      }
      this.loading = false;
    }
  }
};
